pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint256[] memory vs) public {
        // Restrict inputs to avoid reverts in the reference
        vm.assume(contract_address != address(0) && contract_address != address(c));
        vm.assume(tos.length > 0 && vs.length > 0 && tos.length == vs.length);
        // Ensure no address in tos is zero or the contract itself
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0) && tos[i] != address(c));
            vm.assume(vs[i] > 0); // Avoid transfer of zero to prevent revert in ERC20
        }
        // Drive the call
        bool ret;
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(c.transfer.selector, contract_address, tos, vs));
        if (success) {
            ret = abi.decode(data, (bool));
            assertTrue(ret, "transfer should return true on success");
        }
    }
}

