// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[2] memory tos, uint[2] memory vs) public {
        vm.assume(tos[0] != address(0) && tos[0] != address(c));
        vm.assume(tos[1] != address(0) && tos[1] != address(c));
        vm.assume(tos[0] != tos[1]);
        vs[0] = bound(vs[0], 1, 1e18);
        vs[1] = bound(vs[1], 1, 1e18);
        address[] memory tosArr = new address[](2);
        tosArr[0] = tos[0];
        tosArr[1] = tos[1];
        uint[] memory vsArr = new uint[](2);
        vsArr[0] = vs[0];
        vsArr[1] = vs[1];

        uint initialAllowance0 = c.allowance(msg.sender, address(c), tos[0]);
        uint initialAllowance1 = c.allowance(msg.sender, address(c), tos[1]);

        c.transfer(address(c), tosArr, vsArr);

        uint finalAllowance0 = c.allowance(msg.sender, address(c), tos[0]);
        uint finalAllowance1 = c.allowance(msg.sender, address(c), tos[1]);

        assertTrue(finalAllowance0 == initialAllowance0 && finalAllowance1 == initialAllowance1, "Allowance should not change");
    }
}
